    CREATE TABLE [silver].[business_interventions] (
        [intervention_id] NVARCHAR(100) NOT NULL,
        [effective_date] DATE NOT NULL,
        [project] NVARCHAR(4000) NOT NULL,
        [intervention_name] NVARCHAR(4000) NOT NULL,
        [description] NVARCHAR(4000) NOT NULL,
