        [intervention_id],
        [effective_date],
        [project],
        [intervention_name],
        [description],
        [target_kpis],
        [measurement_note]
    )
    SELECT 
        TRY_CONVERT(NVARCHAR(4000), src.[intervention_id]) AS [intervention_id],
        TRY_CONVERT(DATE, (CASE WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))) LIKE N'[12][0-9][0-9][0-9]-%' THEN COALESCE(TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))), 126), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))), 121), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))), 120), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))), 23)) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))) LIKE N'[12][0-9][0-9][0-9]/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))), 111) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))) LIKE N'%/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))), 103) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))) LIKE N'%-%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))), 110) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))) LIKE N'[12][0-9][0-9][0-9][01][0-9][0-3][0-9]' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_date]))), 112) ELSE NULL END)) AS [effective_date],
        TRY_CONVERT(NVARCHAR(4000), src.[project]) AS [project],
        TRY_CONVERT(NVARCHAR(4000), src.[intervention_name]) AS [intervention_name],
        TRY_CONVERT(NVARCHAR(4000), src.[description]) AS [description],
        TRY_CONVERT(NVARCHAR(4000), src.[target_kpis]) AS [target_kpis],
        TRY_CONVERT(NVARCHAR(4000), src.[measurement_note]) AS [measurement_note]
    FROM [bronze].[business_interventions] AS src;

