                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_vnd]))), N',', N'') END)) ELSE NULL END AS [unit_cost_vnd],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[inventory_value_vnd]))), N',', N'') END)) ELSE NULL END AS [inventory_value_vnd],
                CASE WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[stockout_flag])))) IN (N'true', N'1', N'yes', N'y', N't') THEN CAST(1 AS BIT) WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[stockout_flag])))) IN (N'false', N'0', N'no', N'n', N'f') THEN CAST(0 AS BIT) ELSE NULL END AS [stockout_flag],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[reorder_point_qty]))), N',', N'') END)) ELSE NULL END AS [reorder_point_qty],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[safety_stock_qty]))), N',', N'') END)) ELSE NULL END AS [safety_stock_qty]
            FROM [bronze].[inventory_daily_snapshot_raw] AS src
        ) AS transformed
        WHERE transformed.[product_id] IS NULL
    )
        THROW 51003, N'NOT NULL validation failed: inventory_daily_snapshot_raw.product_id', 1;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT 
                TRY_CONVERT(DATE, (CASE WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))) LIKE N'[12][0-9][0-9][0-9]-%' THEN COALESCE(TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))), 126), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))), 121), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))), 120), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))), 23)) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))) LIKE N'[12][0-9][0-9][0-9]/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))), 111) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))) LIKE N'%/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))), 103) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))) LIKE N'%-%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))), 110) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))) LIKE N'[12][0-9][0-9][0-9][01][0-9][0-3][0-9]' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[snapshot_date]))), 112) ELSE NULL END)) AS [snapshot_date],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_id]) AS [warehouse_id],
                TRY_CONVERT(NVARCHAR(4000), src.[product_id]) AS [product_id],
