                TRY_CONVERT(NVARCHAR(4000), src.[invoice_id]) AS [invoice_id],
                TRY_CONVERT(NVARCHAR(4000), src.[sales_order_line_id]) AS [sales_order_line_id],
                TRY_CONVERT(NVARCHAR(4000), src.[product_id]) AS [product_id],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_invoiced]))), N',', N'') END)) ELSE NULL EN