                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[net_amount_vnd]))), N',', N'') END)) ELSE NULL END AS [net_amount_vnd],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[tax_amount_vnd]))), N',', N'') END)) ELSE NULL END AS [tax_amount_vnd],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_total_vnd]))), N',', N'') END)) ELSE NULL END AS [line_total_vnd]
            FROM [bronze].[invoice_lines_raw] AS src
        ) AS transformed
        GROUP BY transformed.[invoice_line_id]
        HAVING COUNT_BIG(*) > 1
    )
        THROW 51005, N'Primary key duplicate after transformation: invoice_lines_raw (invoice_line_id)', 1;

    CREATE TABLE [silver].[invoice_lines] (
        [invoice_line_id] NVARCHAR(100) NOT NULL,
        [invoice_id] NVARCHAR(100) NOT NULL,
        [sales_order_line_id] NVARCHAR(100) NOT NULL,
        [product_id] NVARCHAR(100) NOT NULL,
        [quantity_invoiced] BIGINT NOT NULL,
        [unit_price_vnd] BIGINT NOT NULL,
        [discount_pct] DECIMAL(38,10) NOT NULL,
        [net_amount_vnd] BIGINT NOT NULL,
        [tax_amount_vnd] BIGINT NOT NULL,
        [line_total_vnd] BIGINT NOT NULL
    );

    INSERT INTO [silver].[invoice_lines] (
        [invoice_line_id],
        [invoice_id],
        [sales_order_line_id],
        [product_id],
        [quantity_invoiced],
        [unit_price_vnd],
        [discount_pct],
        [net_amount_vnd],
        [tax_amount_vnd],
        [line_total_vnd]
    )
    SELECT 
        TRY_CONVERT(NVARCHAR(4000), src.[invoice_line_id]) AS [invoice_line_id],
        TRY_CONVERT(NVARCHAR(4000), src.[invoice_id]) AS [invoice_id],
