                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '))))))) = N'direct' THEN N'Direct'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '))))))) = N'direct traffic' THEN N'Direct'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '))))))) = N'referral' THEN N'Referral'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '))))))) = N'partner referral' THEN N'Referral'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '))))))) = N'email' THEN N'Email'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '))))))) = N'edm' THEN N'Email'
                    ELSE LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' ')))
