                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '))))))) = N'fb ads' THEN N'Facebook Ads'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '))))))) = N'meta ads' THEN N'Facebook Ads'
