                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '))))))) = N'partner referral' THEN N'Referral'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '))))))) = N'email' THEN N'Email'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '))))))) = N'edm' THEN N'Email'
                    ELSE LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[source_channel_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' ')))
                END) AS [source_channel],
                TRY_CONVERT(NVARCHAR(4000), src.[campaign_id]) AS [campaign_id],
                TRY_CONVERT(NVARCHAR(4000), src.[product_interest_id]) AS [product_interest_id],
                TRY_CONVERT(NVARCHAR(4000), src.[inquiry_type]) AS [inquiry_type],
                TRY_CONVERT(NVARCHAR(4000), src.[company_size_band]) AS [company_size_band],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[pages_viewed_30d]))), N',', N'') END)) ELSE NULL END AS [pages_viewed_30d],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[form_completeness_pct]))), N',', N'') END)) ELSE NULL END AS [form_completeness_pct],
                CASE WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[requested_quote_flag])))) IN (N'true', N'1', N'yes', N'y', N't') THEN CAST(1 AS BIT) WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[requested_quote_flag])))) IN (N'false', N'0', N'no', N'n', N'f') THEN CAST(0 AS BIT) ELSE NULL END AS [requested_quote_flag],
                CASE WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[requested_sample_flag])))) IN (N'true', N'1', N'yes', N'y', N't') THEN CAST(1 AS BIT) WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[requested_sample_flag])))) IN (N'false', N'0', N'no', N'n', N'f') THEN CAST(0 AS BIT) ELSE NULL END AS [requested_sample_flag],
                TRY_CONVERT(NVARCHAR(4000), src.[budget_status]) AS [budget_status],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[purchase_timeline_days]))), N',', N'') END)) ELSE NULL END AS [purchase_timeline_days],
                TRY_CONVERT(NVARCHAR(4000), src.[assigned_sales_id]) AS [assigned_sales_id],
                TRY_CONVERT(NVARCHAR(4000), src.[lifecycle_status_raw]) AS [lifecycle_status],
                TRY_CONVERT(NVARCHAR(4000), src.[lost_reason_raw]) AS [lost_reason],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_value_vnd]))), N',', N'') END)) ELSE NULL END AS [expected_value_vnd],
                TRY_CONVERT(NVARCHAR(4000), src.[email]) AS [email],
                TRY_CONVERT(NVARCHAR(4000), src.[phone]) AS [phone]
            FROM [bronze].[leads_raw] AS src
        ) AS transformed
        WHERE transformed.[expected_value_vnd] IS NULL
    )
        THROW 51003, N'NOT NULL validation failed: leads_raw.expected_value_vnd', 1;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT DISTINCT 
                TRY_CONVERT(NVARCHAR(4000), src.[lead_id]) AS [lead_id],
                CASE WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))) LIKE N'[12][0-9][0-9][0-9]-%' THEN COALESCE(TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))), 126), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))), 121), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))), 120), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))), 23)) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))) LIKE N'[12][0-9][0-9][0-9]/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))), 111) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))) LIKE N'%/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))), 103) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))) LIKE N'%-%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))), 110) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))) LIKE N'[12][0-9][0-9][0-9][01][0-9][0-3][0-9]' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[created_at]))), 112) ELSE NULL END AS [created_at],
                TRY_CONVERT(NVARCHAR(4000), src.[customer_id]) AS [customer_id],
                TRY_CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[company_name_raw]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' ')))) AS [company_name],
                TRY_CONVERT(NVARCHAR(4000), CASE
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[industry_raw])))) = N'pharma' THEN N'Pharmaceutical'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[industry_raw])))) = N'pharmaceutical' THEN N'Pharmaceutical'
