                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), N',', N'') END)) ELSE NULL END AS [clicks],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), N',', N'') END)) ELSE NULL END AS [sessions],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[spend_vnd]))), N',', N'') END)) ELSE NULL END AS [spend_vnd],
                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[leads_reported]))), N',', N'') END)) ELSE NULL END AS [leads_reported],
                TRY_CONVERT(NVARCHAR(4000), src.[source_platform]) AS [source_platform]
            FROM [bronze].[marketing_daily_raw] AS src
        ) AS transformed
        GROUP BY transformed.[date], transformed.[campaign_id]
        HAVING COUNT_BIG(*) > 1
    )
        THROW 51005, N'Primary key duplicate after transformation: marketing_daily_raw (date, campaign_id)', 1;

    CREATE TABLE [silver].[marketing_daily] (
        [date] DATE NOT NULL,
        [campaign_id] NVARCHAR(100) NOT NULL,
        [channel] NVARCHAR(4000) NOT NULL,
        [impressions] BIGINT NOT NULL,
        [clicks] BIGINT NOT NULL,
        [sessions] BIGINT NOT NULL,
        [spend_vnd] BIGINT NOT NULL,
        [leads_reported] BIGINT NOT NULL,
        [source_platform] NVARCHAR(4000) NOT NULL
    );

    INSERT INTO [silver].[marketing_daily] (
        [date],
        [campaign_id],
        [channel],
        [impressions],
        [clicks],
        [sessions],
        [spend_vnd],
        [leads_reported],
        [source_platform]
    )
    SELECT DISTINCT 
        TRY_CONVERT(DATE, (CASE WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))) LIKE N'[12][0-9][0-9][0-9]-%' THEN COALESCE(TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))), 126), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))), 121), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))), 120), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))), 23)) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))) LIKE N'[12][0-9][0-9][0-9]/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))), 111) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))) LIKE N'%/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))), 103) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))) LIKE N'%-%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))), 110) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))) LIKE N'[12][0-9][0-9][0-9][01][0-9][0-3][0-9]' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[date]))), 112) ELSE NULL END)) AS [date],
        TRY_CONVERT(NVARCHAR(4000), src.[campaign_id]) AS [campaign_id],
        TRY_CONVERT(NVARCHAR(4000), CASE
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'google ads' THEN N'Google Ads'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'google ppc' THEN N'Google Ads'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'gads' THEN N'Google Ads'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'paid search' THEN N'Google Ads'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'facebook ads' THEN N'Facebook Ads'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'fb ads' THEN N'Facebook Ads'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'meta ads' THEN N'Facebook Ads'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'facebook' THEN N'Facebook Ads'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'organic search' THEN N'Organic Search'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'organic' THEN N'Organic Search'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'seo' THEN N'Organic Search'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'direct' THEN N'Direct'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'direct traffic' THEN N'Direct'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'referral' THEN N'Referral'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'partner referral' THEN N'Referral'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'email' THEN N'Email'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[channel])))) = N'edm' THEN N'Email'
            ELSE src.[channel]
        END) AS [channel],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[impressions]))), N',', N'') END)) ELSE NULL END AS [impressions],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[clicks]))), N',', N'') END)) ELSE NULL END AS [clicks],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[sessions]))), N',', N'') END)) ELSE NULL END AS [sessions],
