    IF EXISTS (
        SELECT 1 FROM [bronze].[payments_raw] AS src
        WHERE (src.[payment_date]) IS NOT NULL AND (TRY_CONVERT(DATE, (CASE WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))) LIKE N'[12][0-9][0-9][0-9]-%' THEN COALESCE(TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))), 126), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))), 121), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))), 120), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))), 23)) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))) LIKE N'[12][0-9][0-9][0-9]/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))), 111) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))) LIKE N'%/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))), 103) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))) LIKE N'%-%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))), 110) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))) LIKE N'[12][0-9][0-9][0-9][01][0-9][0-3][0-9]' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[payment_date]))), 112) ELSE NULL END))) IS NULL
    )
