    IF EXISTS (
        SELECT 1 FROM [bronze].[payments_raw] AS src
        WHERE (src.[paid_amount_vnd]) IS NOT NULL AND (CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), N',', N'') END)) ELSE NULL END) IS NULL
