                CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[paid_amount_vnd]))), N',', N'') END)) ELSE NULL END AS [paid_amount_vnd],
                TRY_CONVERT(NVARCHAR(4000), CASE
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[payment_method])))) = N'bank transfer' THEN N'Bank Transfer'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[payment_method])))) = N'wire transfer' THEN N'Bank Transfer'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[payment_method])))) = N'bank' THEN N'Bank Transfer'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[payment_method])))) = N'cash' THEN N'Cash'
                    WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[payment_method])))) = N'offset' THEN N'Offset'
                    ELSE src.[payment_method]
                END) AS [payment_method],
                TRY_CONVERT(NVARCHAR(4000), src.[payment_stage]) AS [payment_stage]
            FROM [bronze].[payments_raw] AS src
