                TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_defect_rate]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_defect_rate]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_defect_rate]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_defect_rate])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[expected_defect_rate]))), N',', N'') END) AS [expected_defect_rate],
