    INSERT INTO [silver].[product_supplier_map] (
        [map_id],
        [product_id],
        [supplier_id],
        [supplier_role],
        [effective_from],
        [effective_to],
        [currency],
        [unit_cost_local],
        [moq_qty],
        [contract_lead_time_days],
        [expected_defect_rate],
        [freight_mode]
    )
    SELECT 
        TRY_CONVERT(NVARCHAR(4000), src.[map_id]) AS [map_id],
        TRY_CONVERT(NVARCHAR(4000), src.[product_id]) AS [product_id],
        TRY_CONVERT(NVARCHAR(4000), src.[supplier_id]) AS [supplier_id],
        TRY_CONVERT(NVARCHAR(4000), src.[supplier_role]) AS [supplier_role],
        TRY_CONVERT(DATE, (CASE WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))) LIKE N'[12][0-9][0-9][0-9]-%' THEN COALESCE(TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))), 126), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))), 121), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))), 120), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))), 23)) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))) LIKE N'[12][0-9][0-9][0-9]/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))), 111) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))) LIKE N'%/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))), 103) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))) LIKE N'%-%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))), 110) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))) LIKE N'[12][0-9][0-9][0-9][01][0-9][0-3][0-9]' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_from]))), 112) ELSE NULL END)) AS [effective_from],
        TRY_CONVERT(DATE, (CASE WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))) LIKE N'[12][0-9][0-9][0-9]-%' THEN COALESCE(TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))), 126), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))), 121), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))), 120), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))), 23)) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))) LIKE N'[12][0-9][0-9][0-9]/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))), 111) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))) LIKE N'%/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))), 103) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))) LIKE N'%-%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))), 110) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))) LIKE N'[12][0-9][0-9][0-9][01][0-9][0-3][0-9]' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[effective_to]))), 112) ELSE NULL END)) AS [effective_to],
        TRY_CONVERT(NVARCHAR(4000), CASE
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'$') THEN N'USD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'CNY') THEN N'CNY'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'EUR') THEN N'EUR'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'GBP') THEN N'GBP'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'JPY') THEN N'JPY'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'MYR') THEN N'MYR'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'RMB') THEN N'CNY'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'SGD') THEN N'SGD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'THB') THEN N'THB'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'US$') THEN N'USD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'USD') THEN N'USD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'VND') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'VND.') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'VNĐ') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'Đ') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'€') THEN N'EUR'
            ELSE UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency]))))
        END) AS [currency],
        TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_local]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_local]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_local]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_local])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_cost_local]))), N',', N'') END) AS [unit_cost_local],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[moq_qty]))), N',', N'') END)) ELSE NULL END AS [moq_qty],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), N',', N'') END)) ELSE NULL END AS [contract_lead_time_days],
