    CREATE TABLE [silver].[products] (
        [product_id] NVARCHAR(100) NOT NULL,
        [sku] NVARCHAR(4000) NOT NULL,
        [product_name] NVARCHAR(4000) NOT NULL,
        [product_category] NVARCHAR(4000) NOT NULL,
        [product_family] NVARCHAR(4000) NOT NULL,
        [brand] NVARCHAR(4000) NOT NULL,
        [source_country] NVARCHAR(4000) NOT NULL,
        [standard_cost_vnd] BIGINT NOT NULL,
        [list_price_vnd] BIGINT NOT NULL,
        [shelf_life_days] BIGINT NULL,
        [criticality] NVARCHAR(4000) NOT NULL,
        [base_reorder_point_qty] BIGINT NOT NULL,
        [base_safety_stock_qty] BIGINT NOT NULL,
        [popularity_rank] BIGINT NOT NULL
    );

    INSERT INTO [silver].[products] (
        [product_id],
        [sku],
        [product_name],
        [product_category],
        [product_family],
        [brand],
        [source_country],
        [standard_cost_vnd],
        [list_price_vnd],
        [shelf_life_days],
        [criticality],
        [base_reorder_point_qty],
        [base_safety_stock_qty],
        [popularity_rank]
    )
    SELECT 
        TRY_CONVERT(NVARCHAR(4000), src.[product_id]) AS [product_id],
        TRY_CONVERT(NVARCHAR(4000), src.[sku]) AS [sku],
        TRY_CONVERT(NVARCHAR(4000), LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR(4000), src.[product_name]), CHAR(9), N' '), CHAR(13), N' '), CHAR(10), N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' '), N'  ', N' ')))) AS [product_name],
        TRY_CONVERT(NVARCHAR(4000), CASE
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[product_category])))) = N'cleanroom wipers' THEN N'Cleanroom Wipers'
            WHEN LOWER(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[product_category])))) = N'disinfectants' THEN N'Disinfectants'
            ELSE src.[product_category]
        END) AS [product_category],
        TRY_CONVERT(NVARCHAR(4000), src.[product_family]) AS [product_family],
        TRY_CONVERT(NVARCHAR(4000), src.[brand]) AS [brand],
        TRY_CONVERT(NVARCHAR(4000), src.[source_country]) AS [source_country],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[standard_cost_vnd]))), N',', N'') END)) ELSE NULL END AS [st