', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[contract_lead_time_days]))), N',', N'') END)) ELSE NULL END AS [contract_lead_time_days]
            FROM [bronze].[purchase_order_lines_raw] AS src
