    CREATE TABLE [silver].[purchase_order_lines] (
        [purchase_order_line_id] NVARCHAR(100) NOT NULL,
        [purchase_order_id] NVARCHAR(100) NOT NULL,
        [product_id] NVARCHAR(100) NOT NULL,
        [quantity_ordered] BIGINT NOT NULL,
        [unit_price_local] DECIMAL(38,10) NOT NULL,
        [currency] NVARCHAR(4000) NOT NULL,
        [fx_rate_to_vnd] DECIMAL(38,10) NOT NULL,
        [merchandise_value_vnd] BIGINT NOT NULL,
        [freight_cost_vnd] BIGINT NOT NULL,
        [customs_cost_vnd] BIGINT NOT NULL,
        [expedite_cost_vnd] BIGINT NOT NULL,
        [supplier_role] NVARCHAR(4000) NOT NULL,
        [contract_lead_time_days] BIGINT NOT NULL
    );

    INSERT INTO [silver].[purchase_order_lines] (
        [purchase_order_line_id],
        [purchase_order_id],
        [product_id],
        [quantity_ordered],
        [unit_price_local],
        [currency],
        [fx_rate_to_vnd],
        [merchandise_value_vnd],
        [freight_cost_vnd],
        [customs_cost_vnd],
        [expedite_cost_vnd],
        [supplier_role],
        [contract_lead_time_days]
    )
    SELECT 
        TRY_CONVERT(NVARCHAR(4000), src.[purchase_order_line_id]) AS [purchase_order_line_id],
        TRY_CONVERT(NVARCHAR(4000), src.[purchase_order_id]) AS [purchase_order_id],
        TRY_CONVERT(NVARCHAR(4000), src.[product_id]) AS [product_id],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity_ordered]))), N',', N'') END)) ELSE NULL END AS [quantity_ordered],
        TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_price_local]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_price_local]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_price_local]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_price_local])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_price_local]))), N',', N'') END) AS [unit_price_local],
        TRY_CONVERT(NVARCHAR(4000), CASE
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'$') THEN N'USD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'CNY') THEN N'CNY'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'EUR') THEN N'EUR'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'GBP') THEN N'GBP'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'JPY') THEN N'JPY'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'MYR') THEN N'MYR'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'RMB') THEN N'CNY'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'SGD') THEN N'SGD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'THB') THEN N'THB'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'US$') THEN N'USD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'USD') THEN N'USD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'VND') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'VND.') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'VNĐ') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'Đ') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'€') THEN N'EUR'
            ELSE UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency]))))
        END) AS [currency],
        TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[fx_rate_to_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[fx_rate_to_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[fx_rate_to_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[fx_rate_to_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[fx_rate_to_vnd]))), N',', N'') END) AS [fx_rate_to_vnd],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[merchandise_value_vnd]))), N',', N'') END)) ELSE NULL END AS [merchandise_value_vnd],
