HAR(4000), src.[estimated_quality_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), N',', N'') END)) ELSE NULL END AS [estimated_quality_cost_vnd],
