    CREATE TABLE [silver].[qa_events] (
        [qa_event_id] NVARCHAR(100) NOT NULL,
        [event_date] DATE NOT NULL,
        [purchase_order_id] NVARCHAR(100) NOT NULL,
        [purchase_order_line_id] NVARCHAR(100) NOT NULL,
        [product_id] NVARCHAR(100) NOT NULL,
        [supplier_id] NVARCHAR(100) NOT NULL,
        [qa_type] NVARCHAR(4000) NOT NULL,
        [severity] NVARCHAR(4000) NOT NULL,
        [defect_qty] BIGINT NOT NULL,
        [estimated_quality_cost_vnd] BIGINT NOT NULL,
        [disposition] NVARCHAR(4000) NOT NULL
    );

    INSERT INTO [silver].[qa_events] (
        [qa_event_id],
        [event_date],
        [purchase_order_id],
        [purchase_order_line_id],
        [product_id],
        [supplier_id],
        [qa_type],
        [severity],
        [defect_qty],
        [estimated_quality_cost_vnd],
        [disposition]
    )
    SELECT 
        TRY_CONVERT(NVARCHAR(4000), src.[qa_event_id]) AS [qa_event_id],
        TRY_CONVERT(DATE, (CASE WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))) LIKE N'[12][0-9][0-9][0-9]-%' THEN COALESCE(TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))), 126), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))), 121), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))), 120), TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))), 23)) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))) LIKE N'[12][0-9][0-9][0-9]/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))), 111) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))) LIKE N'%/%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))), 103) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))) LIKE N'%-%' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))), 110) WHEN LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))) LIKE N'[12][0-9][0-9][0-9][01][0-9][0-3][0-9]' THEN TRY_CONVERT(DATETIME2, LTRIM(RTRIM(CONVERT(NVARCHAR(100), src.[event_date]))), 112) ELSE NULL END)) AS [event_date],
        TRY_CONVERT(NVARCHAR(4000), src.[purchase_order_id]) AS [purchase_order_id],
        TRY_CONVERT(NVARCHAR(4000), src.[purchase_order_line_id]) AS [purchase_order_line_id],
        TRY_CONVERT(NVARCHAR(4000), src.[product_id]) AS [product_id],
        TRY_CONVERT(NVARCHAR(4000), src.[supplier_id]) AS [supplier_id],
        TRY_CONVERT(NVARCHAR(4000), src.[qa_type]) AS [qa_type],
        TRY_CONVERT(NVARCHAR(4000), src.[severity]) AS [severity],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[defect_qty]))), N',', N'') END)) ELSE NULL END AS [defect_qty],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[estimated_quality_cost_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000