    CREATE TABLE [silver].[quotation_lines] (
        [quotation_line_id] NVARCHAR(100) NOT NULL,
        [quotation_id] NVARCHAR(100) NOT NULL,
        [product_id] NVARCHAR(100) NOT NULL,
        [quantity] BIGINT NOT NULL,
        [unit_price_local] DECIMAL(38,10) NOT NULL,
        [currency] NVARCHAR(4000) NOT NULL,
        [discount_pct] DECIMAL(38,10) NOT NULL,
        [line_net_vnd] BIGINT NOT NULL
    );

    INSERT INTO [silver].[quotation_lines] (
        [quotation_line_id],
        [quotation_id],
        [product_id],
        [quantity],
        [unit_price_local],
        [currency],
        [discount_pct],
        [line_net_vnd]
    )
    SELECT 
        TRY_CONVERT(NVARCHAR(4000), src.[quotation_line_id]) AS [quotation_line_id],
        TRY_CONVERT(NVARCHAR(4000), src.[quotation_id]) AS [quotation_id],
        TRY_CONVERT(NVARCHAR(4000), src.[product_id]) AS [product_id],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[quantity]))), N',', N'') END)) ELSE NULL END AS [quantity],
        TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_price_local]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_price_local]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_price_local]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_price_local])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[unit_price_local]))), N',', N'') END) AS [unit_price_local],
        TRY_CONVERT(NVARCHAR(4000), CASE
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'$') THEN N'USD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'CNY') THEN N'CNY'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'EUR') THEN N'EUR'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'GBP') THEN N'GBP'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'JPY') THEN N'JPY'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'MYR') THEN N'MYR'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'RMB') THEN N'CNY'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'SGD') THEN N'SGD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'THB') THEN N'THB'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'US$') THEN N'USD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'USD') THEN N'USD'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'VND') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'VND.') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'VNĐ') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'Đ') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'€') THEN N'EUR'
            ELSE UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency]))))
        END) AS [currency],
        TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[discount_pct]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[discount_pct]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[discount_pct]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[discount_pct])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[discount_pct]))), N',', N'') END) AS [discount_pct],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[line_net_vnd]))), N',', N'') END)) ELSE NULL END AS [line_net_vnd]
    FROM [bronze].[quotation_lines_raw] AS src;

