    CREATE TABLE [silver].[shipments] (
        [shipment_id] NVARCHAR(100) NOT NULL,
        [sales_order_id] NVARCHAR(100) NOT NULL,
        [ship_date] DATE NOT NULL,
        [actual_delivery_date] DATE NOT NULL,
        [shipping_method] NVARCHAR(4000) NOT NULL,
        [warehouse_id] NVARCHAR(100) NOT NULL,
        [freight_cost_vnd] BIGINT NOT NULL,
        [shipment_status] NVARCHAR(4000) NOT NULL,
        [partial_shipment_flag] BIT NOT NULL,
        [tracking_no] NVARCHAR(4000) NOT NULL
    );

