            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'VND.') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'VNĐ') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'Đ') THEN N'VND'
            WHEN UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency])))) = UPPER(N'€') THEN N'EUR'
            ELSE UPPER(LTRIM(RTRIM(CONVERT(NVARCHAR(50), src.[currency]))))
        END) AS [currency],
        TRY_CONVERT(NVARCHAR(4000), src.[payment_term]) AS [payment_term],
        TRY_CONVERT(NVARCHAR(4000), src.[incoterm]) AS [incoterm],
        CASE WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), N',', N'') END) IS NULL THEN NULL WHEN TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), N',', N'') END) = FLOOR(TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), N',', N'') END)) THEN TRY_CONVERT(BIGINT, TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[planned_lead_time_days]))), N',', N'') END)) ELSE NULL END AS [planned_lead_time_days],
        TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[baseline_otif]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[baseline_otif]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[baseline_otif]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[baseline_otif])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[baseline_otif]))), N',', N'') END) AS [baseline_otif],
        TRY_CONVERT(DECIMAL(38,10), CASE WHEN LEFT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[baseline_defect_rate]))), 1) = N'(' AND RIGHT(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[baseline_defect_rate]))), 1) = N')' THEN N'-' + REPLACE(SUBSTRING(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[baseline_defect_rate]))), 2, LEN(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[baseline_defect_rate])))) - 2), N',', N'') ELSE REPLACE(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), src.[baseline_defect_rate]))), N',', N'') END) AS [baseline_defect_rate],
        TRY_CONVERT(NVARCHAR(4000), src.[default_freight_mode]) AS [default_freight_mode]
    FROM [bronze].[suppliers_raw] AS src;

    /* ------------------------------------------------------------
       TABLE: bronze.warehouses -> silver.warehouses
       ------------------------------------------------------------ */
    -- No Data Quality decisions were attached to this table.

    IF OBJECT_ID(N'silver.warehouses', N'U') IS NOT NULL
        THROW 51000, N'Target table silver.warehouses already exists. Review/drop/rename it manually before rebuild.', 1;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT 
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_id]) AS [warehouse_id],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_name]) AS [warehouse_name],
                TRY_CONVERT(NVARCHAR(4000), src.[city]) AS [city],
                TRY_CONVERT(NVARCHAR(4000), src.[province]) AS [province],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_type]) AS [warehouse_type]
            FROM [bronze].[warehouses] AS src
        ) AS transformed
        WHERE DATALENGTH(CONVERT(NVARCHAR(4000), transformed.[warehouse_id])) > 200
    )
        THROW 51006, N'Key/FK value exceeds NVARCHAR(100): warehouses.warehouse_id', 1;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT 
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_id]) AS [warehouse_id],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_name]) AS [warehouse_name],
                TRY_CONVERT(NVARCHAR(4000), src.[city]) AS [city],
                TRY_CONVERT(NVARCHAR(4000), src.[province]) AS [province],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_type]) AS [warehouse_type]
            FROM [bronze].[warehouses] AS src
        ) AS transformed
        WHERE transformed.[warehouse_id] IS NULL
    )
        THROW 51003, N'NOT NULL validation failed: warehouses.warehouse_id', 1;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT 
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_id]) AS [warehouse_id],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_name]) AS [warehouse_name],
                TRY_CONVERT(NVARCHAR(4000), src.[city]) AS [city],
                TRY_CONVERT(NVARCHAR(4000), src.[province]) AS [province],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_type]) AS [warehouse_type]
            FROM [bronze].[warehouses] AS src
        ) AS transformed
        WHERE transformed.[warehouse_name] IS NULL
    )
        THROW 51003, N'NOT NULL validation failed: warehouses.warehouse_name', 1;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT 
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_id]) AS [warehouse_id],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_name]) AS [warehouse_name],
                TRY_CONVERT(NVARCHAR(4000), src.[city]) AS [city],
                TRY_CONVERT(NVARCHAR(4000), src.[province]) AS [province],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_type]) AS [warehouse_type]
            FROM [bronze].[warehouses] AS src
        ) AS transformed
        WHERE transformed.[city] IS NULL
    )
        THROW 51003, N'NOT NULL validation failed: warehouses.city', 1;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT 
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_id]) AS [warehouse_id],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_name]) AS [warehouse_name],
                TRY_CONVERT(NVARCHAR(4000), src.[city]) AS [city],
                TRY_CONVERT(NVARCHAR(4000), src.[province]) AS [province],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_type]) AS [warehouse_type]
            FROM [bronze].[warehouses] AS src
        ) AS transformed
        WHERE transformed.[province] IS NULL
    )
        THROW 51003, N'NOT NULL validation failed: warehouses.province', 1;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT 
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_id]) AS [warehouse_id],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_name]) AS [warehouse_name],
                TRY_CONVERT(NVARCHAR(4000), src.[city]) AS [city],
                TRY_CONVERT(NVARCHAR(4000), src.[province]) AS [province],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_type]) AS [warehouse_type]
            FROM [bronze].[warehouses] AS src
        ) AS transformed
        WHERE transformed.[warehouse_type] IS NULL
    )
        THROW 51003, N'NOT NULL validation failed: warehouses.warehouse_type', 1;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT 
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_id]) AS [warehouse_id],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_name]) AS [warehouse_name],
                TRY_CONVERT(NVARCHAR(4000), src.[city]) AS [city],
                TRY_CONVERT(NVARCHAR(4000), src.[province]) AS [province],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_type]) AS [warehouse_type]
            FROM [bronze].[warehouses] AS src
        ) AS transformed
        WHERE transformed.[warehouse_id] IS NULL
    )
        THROW 51004, N'Primary key contains NULL: warehouses (warehouse_id)', 1;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT 
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_id]) AS [warehouse_id],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_name]) AS [warehouse_name],
                TRY_CONVERT(NVARCHAR(4000), src.[city]) AS [city],
                TRY_CONVERT(NVARCHAR(4000), src.[province]) AS [province],
                TRY_CONVERT(NVARCHAR(4000), src.[warehouse_type]) AS [warehouse_type]
            FROM [bronze].[warehouses] AS src
        ) AS transformed
        GROUP BY transformed.[warehouse_id]
        HAVING COUNT_BIG(*) > 1
    )
        THROW 51005, N'Primary key duplicate after transformation: warehouses (warehouse_id)', 1;

    CREATE TABLE [silver].[warehouses] (
        [warehouse_id] NVARCHAR(100) NOT NULL,
        [warehouse_name] NVARCHAR(4000) NOT NULL,
        [city] NVARCHAR(4000) NOT NULL,
        [province] NVARCHAR(4000) NOT NULL,
        [warehouse_type] NVARCHAR(4000) NOT NULL
    );

    INSERT INTO [silver].[warehouses] (
        [warehouse_id],
        [warehouse_name],
        [city],
        [province],
        [warehouse_type]
    )
    SELECT 
        TRY_CONVERT(NVARCHAR(4000), src.[warehouse_id]) AS [warehouse_id],
        TRY_CONVERT(NVARCHAR(4000), src.[warehouse_name]) AS [warehouse_name],
        TRY_CONVERT(NVARCHAR(4000), src.[city]) AS [city],
        TRY_CONVERT(NVARCHAR(4000), src.[province]) AS [province],
