    WHERE c.[supplier_id] IS NOT NULL AND p.[supplier_id] IS NULL;
END
ELSE
    PRINT N'SKIP FK validation: silver.supplier_payments or silver.suppliers does not exist.';

-- Physical FK relationships created in Silver
SELECT
    fk.name AS foreign_key_name,
    OBJECT_SCHEMA_NAME(fk.parent_object_id) AS child_schema,
    OBJECT_NAME(fk.parent_object_id) AS child_table,
    OBJECT_SCHEMA_NAME(fk.referenced_object_id) AS parent_schema,
    OBJECT_NAME(fk.referenced_object_id) AS parent_table
FROM sys.foreign_keys AS fk
WHERE OBJECT_SCHEMA_NAME(fk.parent_object_id) = N'silver'
ORDER BY child_table, foreign_key_name;
